const rows = items.map(i => i.json);
const webhookBody = $('Webhook').first().json.body;
const clientePlacaNorm = (webhookBody.placa || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const tipo = webhookBody.tipo_agendamento;

const pegar = (obs, termo) => {
  const regex = new RegExp(termo + '[:\s-]*(.*)', 'i');
  const match = (obs || '').match(regex);
  return match ? match[1].split('\r')[0].split('\n')[0].trim() : null;
};
const normPlaca = (p) => (p || '').toUpperCase().replace(/[^A-Z0-9]/g, '');

if (!rows.length || !rows[0].Nome) {
  return [{ json: { _source: 'sql' } }];
}

const base = rows[0];

const parsed = rows.map(o => {
  const obs = o['Observações'] || '';
  const placaRetirada = pegar(obs, 'PLACA RETIRADA EXTERNA') || pegar(obs, 'PLACA RETIRADA');
  const placaInstalacao = pegar(obs, 'PLACA INSTALAÇÃO');
  const plano = pegar(obs, 'PLANO ATUAL') || pegar(obs, 'Plano');
  const taxa = pegar(obs, 'TAXA') || pegar(obs, 'V Instalação');
  const placaRelevante = tipo === 'Retirada' ? placaRetirada : placaInstalacao;
  return { plano, taxa, fpgto: o.FPgto, placaRelevanteNorm: normPlaca(placaRelevante) };
});

const matched = parsed.find(o => o.placaRelevanteNorm && o.placaRelevanteNorm === clientePlacaNorm);
const chosen = matched || parsed[0] || {};

return [{
  json: {
    _source: 'sql',
    Nome: base.Nome,
    CGCCPF: base.CGCCPF,
    Fone1: base.Fone1,
    Celular: base.Celular,
    CodCliente: base.CodCliente,
    VeiculoPlaca: base.VeiculoPlaca || null,
    VeiculoModelo: base.VeiculoModelo || null,
    plano: chosen.plano || null,
    valor_adesao: chosen.taxa || null,
    forma_pagamento: chosen.fpgto || null,
  },
}];

const all = items.map(i => i.json);
const sqlItem = all.find(x => x._source === 'sql' && x.Nome);
const gestaoItem = all.find(x => x._source === 'SistemaGestao' && (x.nome || x.associado));
let origem = 'none';
let nome = null, documento = null, telefone = null;
let cod_cliente = null, veiculo_placa = null, veiculo_modelo = null, plano = null, valor_adesao = null, forma_pagamento = null;
if (sqlItem) {
  origem = 'sql_server';
  nome = sqlItem.Nome || null;
  documento = sqlItem.CGCCPF || null;
  telefone = sqlItem.Celular || sqlItem.Fone1 || null;
  cod_cliente = sqlItem.CodCliente || null;
  veiculo_placa = sqlItem.VeiculoPlaca || null;
  veiculo_modelo = sqlItem.VeiculoModelo || null;
  plano = sqlItem.plano || null;
  valor_adesao = sqlItem.valor_adesao || null;
  forma_pagamento = sqlItem.forma_pagamento || null;
} else if (gestaoItem) {
  origem = 'SistemaGestao';
  const a = gestaoItem.associado || gestaoItem;
  nome = a.nome || null;
  documento = a.cpf || null;
  telefone = a.telefone_whatsapp || a.telefone_fixo || null;
  cod_cliente = a.cod_associado || null;
  const veiculo = (gestaoItem.veiculos || a.veiculos || [])[0] || {};
  veiculo_placa = veiculo.placa || null;
  veiculo_modelo = veiculo.modelo || null;
  plano = veiculo.nome_plano || null;
}
const protocolo = $('Gerar Protocolo').first().json.protocolo;
return [{
  json: {
    encontrado: origem !== 'none',
    origem,
    nome,
    documento,
    telefone,
    protocolo,
    cod_cliente,
    veiculo_placa,
    veiculo_modelo,
    plano,
    valor_adesao,
    forma_pagamento,
  },
}];

const now = new Date();
const y = now.getFullYear();
const m = String(now.getMonth()+1).padStart(2,'0');
const d = String(now.getDate()).padStart(2,'0');
const rand = Math.random().toString(36).slice(2,7).toUpperCase();
const protocolo = `AG-${y}${m}${d}-${rand}`;
return items.map(i => ({ json: { ...i.json, protocolo } }));

const src = $('Gerar Protocolo').first().json;
const b = src.body;
const proto = src.protocolo;
const modelo = $json.Modelo || null;

// sem acento na chave de busca: o valor vem como "Parque Dois Irmãos"
const SEDES = [
  { chave: 'MESSEJANA', endereco: 'Av. Gurgel do Amaral, 1037 - Messejana, Fortaleza - CE, 60810-360' },
  { chave: 'DOIS IRM', endereco: 'R. A (Lot. Parque Montenegro 1), 981 - Parque Dois Irmãos, Fortaleza - CE, 60540-256' },
];

const sedeNome = String(b.sede == null ? '' : b.sede).trim();
const ehSede = sedeNome.length > 0;
let sedeEndereco = '';
if (ehSede) {
  const alvo = sedeNome.toUpperCase();
  for (const s of SEDES) {
    if (alvo.indexOf(s.chave) >= 0) { sedeEndereco = s.endereco; break; }
  }
}

let agenda = '';
if (b.data_formatada && b.turno) {
  agenda = `📅 Data: ${b.data_formatada} - Turno: ${b.turno}`;
}

const placaTexto = b.placa || 'Não informado';
const placaLinha = modelo ? `🚗 Placa: ${placaTexto} (${modelo})` : `🚗 Placa: ${placaTexto}`;

