  const clienteAchado = !!(fonte && fonte.encontrado);

  if (clienteAchado) {
    motivoTexto = 'Veiculo nao encontrado no cadastro do cliente na ' + sistema + ' (codigo ' + fonte.cod_cliente + ') - confirme a placa.';
  } else {
    motivoTexto = 'Cliente nao encontrado nem na Empresa Exemplo nem na Marca C - provavel cadastro novo.';
  }

