const normPlaca = (v) => String(v == null ? '' : v).toUpperCase().replace(/[^A-Z0-9]/g, '');

const cpfAlvo = soDigitos(decidido.documento || body.documento);
if (!cpfAlvo) return [{ json: { found: false, motivo: 'sem_cpf' } }];

const placaAlvo = normPlaca(body.placa);
const rows = items.map(i => i.json);
const candidatos = rows.filter(r => soDigitos(r.CPF) === cpfAlvo);

if (candidatos.length === 0) return [{ json: { found: false, motivo: 'cpf_nao_encontrado' } }];

// 1) CPF + placa: único jeito de saber QUAL veículo quando o associado tem várias linhas (adição)
if (placaAlvo) {
  const porPlaca = candidatos.find(r => normPlaca(r.PLACA) === placaAlvo);
  if (porPlaca) {
    return [{ json: { found: true, row_number: porPlaca.row_number, criterio: 'cpf_placa' } }];
  }
}

// 2) linha única: não existe ambiguidade possível, então marca mesmo se a placa não bater
//    (cobre erro de digitação do cliente no formulário e linha antiga sem placa)
if (candidatos.length === 1) {
  return [{ json: { found: true, row_number: candidatos[0].row_number, criterio: 'cpf_unico' } }];
}

// 3) várias linhas e nenhuma placa batendo: não dá pra saber qual veículo é.
//    Marcar a linha errada vincularia o veículo à OS errada, então prefere não marcar.
return [{ json: { found: false, motivo: 'ambiguo', candidatos: candidatos.length } }];

