function soDigitos(v) { return String(v == null ? '' : v).replace(/[^0-9]/g, ''); }
function formatarCPF(v) {
  const d = soDigitos(v);
  if (d.length === 11) return d.slice(0,3) + '.' + d.slice(3,6) + '.' + d.slice(6,9) + '-' + d.slice(9);
